select case when discount_pct >= 0.33 then 'HIGH' else 'LOW' end as discount_pct_tier, promo_code, approx_percentile(discount_pct, array(0.25, 0.5, 0.75)) as discount_pct_quartiles, round(sum(discount_pct) / nullif(count(case when promo_code = 'VIP' then 1 end), 0), 2) as discount_pct_per_vip, grouping_id() as grouping_level from promotions group by rollup (case when discount_pct >= 0.33 then 'HIGH' else 'LOW' end, promo_code) order by promo_code desc
